"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["32865"],{92286(e){e.exports=JSON.parse('{"id":"FUT-1666","slug":"weighted-average-cost-of-capital","term":"Weighted Average Cost of Capital (WACC)","also_known_as":["WACC"],"difficulty":"Intermediate","definition":"The weighted average cost of capital (WACC) is the average rate of return a company must pay to all its funders, lenders and shareholders, weighted by how much of each type of funding it uses.","explanation":["Companies fund themselves with a mix of debt and equity, and each has a different cost. WACC combines them into one figure by weighting each cost by its share of total funding. Because interest is usually tax-deductible, the cost of debt is used after tax.","Suppose a company is funded 60% by equity and 40% by debt. Shareholders require 10%, lenders charge 6% and the tax rate is 25%, so the after-tax cost of debt is 4.5%. The WACC is 60% of 10% plus 40% of 4.5%, which is 6% plus 1.8%, giving 7.8%.","WACC is widely used as the discount rate when valuing a company\'s future cash flows and as the hurdle rate for new investments. A project expected to earn more than the WACC should create value; one that earns less should not.","WACC rests on estimates, especially the cost of equity, which cannot be observed directly. Small changes in assumptions can change it noticeably, which in turn can make large differences in valuations."],"note":"","total":1500,"prev":{"slug":"weighted-average-cost-method","term":"Weighted Average Cost Method"},"next":{"slug":"what-if-analysis","term":"What-If Analysis"}}')}}]);